<?php include '_layout_start.php'; $pdo=db(); echo '<h1>Content Blocks</h1><div class="lead-box"><p>This module is ready for admin-updatable sections such as Live News, Hall of Fame, Testimonials, Video Gallery, Notices and Events.</p>'; if(!$pdo){echo '<div class="alert alert-warning">Import database/install.sql to activate content editing.</div>';} else { if($_SERVER['REQUEST_METHOD']==='POST'){ $stmt=$pdo->prepare('REPLACE INTO content_blocks (`key`,`title`,`content`,`updated_at`) VALUES (?,?,?,NOW())'); $stmt->execute([$_POST['key'],$_POST['title'],$_POST['content']]); echo '<div class="alert alert-success">Saved.</div>'; } echo '<form method="post" class="row g-3"><div class="col-md-4"><input class="form-control" name="key" placeholder="live_news" required></div><div class="col-md-8"><input class="form-control" name="title" placeholder="Title" required></div><div class="col-12"><textarea class="form-control" name="content" rows="5" placeholder="Content"></textarea></div><div><button class="btn btn-primary">Save Block</button></div></form>'; } echo '</div>'; include '_layout_end.php'; ?>
